$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.IO.Compression

$root = $PSScriptRoot
$outDir = Join-Path $root 'output'
$tmpDir = Join-Path $root 'tmp_uat_docx'
$outFile = Join-Path $outDir 'LearnSync_User_Acceptance_Test.docx'
if (Test-Path -LiteralPath $tmpDir) { Remove-Item -LiteralPath $tmpDir -Recurse -Force }
New-Item -ItemType Directory -Force -Path $outDir, $tmpDir, (Join-Path $tmpDir '_rels'), (Join-Path $tmpDir 'word'), (Join-Path $tmpDir 'word\_rels'), (Join-Path $tmpDir 'docProps') | Out-Null

function X([string]$s) { [Security.SecurityElement]::Escape($s) }
$sb = [Text.StringBuilder]::new()
[void]$sb.Append('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>')
function P([string]$text='', [int]$size=20, [bool]$bold=$false, [string]$align='left', [int]$before=0, [int]$after=120, [string]$color='000000') {
  $b = if($bold){'<w:b/>'}else{''}; $jc = if($align -eq 'center'){'center'}elseif($align -eq 'right'){'right'}else{'left'}
  [void]$sb.Append("<w:p><w:pPr><w:spacing w:before=`"$before`" w:after=`"$after`"/><w:jc w:val=`"$jc`"/></w:pPr><w:r><w:rPr>$b<w:sz w:val=`"$size`"/><w:szCs w:val=`"$size`"/><w:color w:val=`"$color`"/><w:rFonts w:ascii=`"Aptos`" w:hAnsi=`"Aptos`"/></w:rPr><w:t xml:space=`"preserve`">$(X $text)</w:t></w:r></w:p>")
}
function PageBreak { [void]$sb.Append('<w:p><w:r><w:br w:type="page"/></w:r></w:p>') }
function Bullet([string]$text) { [void]$sb.Append("<w:p><w:pPr><w:ind w:left=`"360`" w:hanging=`"180`"/><w:spacing w:after=`"50`"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val=`"20`"/></w:rPr><w:t>• </w:t></w:r><w:r><w:rPr><w:sz w:val=`"20`"/><w:rFonts w:ascii=`"Aptos`" w:hAnsi=`"Aptos`"/></w:rPr><w:t xml:space=`"preserve`">$(X $text)</w:t></w:r></w:p>") }
function Tbl([string[]]$heads, [object[]]$rows, [int[]]$widths) {
  [void]$sb.Append('<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="D9D9D9"/><w:left w:val="single" w:sz="4" w:color="D9D9D9"/><w:bottom w:val="single" w:sz="4" w:color="D9D9D9"/><w:right w:val="single" w:sz="4" w:color="D9D9D9"/><w:insideH w:val="single" w:sz="4" w:color="D9D9D9"/><w:insideV w:val="single" w:sz="4" w:color="D9D9D9"/></w:tblBorders><w:tblCellMar><w:top w:w="80" w:type="dxa"/><w:left w:w="90" w:type="dxa"/><w:bottom w:w="80" w:type="dxa"/><w:right w:w="90" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>')
  foreach($w in $widths){[void]$sb.Append("<w:gridCol w:w=`"$w`"/>")}; [void]$sb.Append('</w:tblGrid>')
  $all = @($heads) + @($rows)
  for($ri=0;$ri -lt $all.Count;$ri++) { $isHead=$ri -eq 0; $vals=@($all[$ri]); [void]$sb.Append('<w:tr>')
    for($ci=0;$ci -lt $heads.Count;$ci++) { $fill=if($isHead){'1F4E79'}elseif(($ri%2)-eq 0){'EAF3F8'}else{'FFFFFF'}; $txt=[string]$vals[$ci]; $b=if($isHead){'<w:b/>'}else{''}; $col=if($isHead){'FFFFFF'}else{'000000'}; $jc=if($ci -eq 0 -or $ci -eq ($heads.Count-1)){'center'}else{'left'}
      [void]$sb.Append("<w:tc><w:tcPr><w:tcW w:w=`"$($widths[$ci])`" w:type=`"dxa`"/><w:shd w:val=`"clear`" w:fill=`"$fill`"/><w:vAlign w:val=`"center`"/></w:tcPr><w:p><w:pPr><w:jc w:val=`"$jc`"/><w:spacing w:after=`"0`"/></w:pPr><w:r><w:rPr>$b<w:sz w:val=`"16`"/><w:szCs w:val=`"16`"/><w:color w:val=`"$col`"/><w:rFonts w:ascii=`"Aptos`" w:hAnsi=`"Aptos`"/></w:rPr><w:t xml:space=`"preserve`">$(X $txt)</w:t></w:r></w:p></w:tc>")
    }; [void]$sb.Append('</w:tr>')
  }; [void]$sb.Append('</w:tbl>'); P '' 8 $false 'left' 0 80
}

# Cover
P '' 20 $false 'left' 700 100
P 'LEARN SYNC' 38 $true 'center' 0 60 '1F4E79'
P 'USER ACCEPTANCE TEST' 44 $true 'center' 0 120 '000000'
P 'Test Protocol, Task Records, Results Summary, and Sign Off' 24 $false 'center' 0 420 '000000'
P 'Purpose' 22 $true 'left' 0 70
P 'This document provides a structured, participant based User Acceptance Test for LearnSync. It records whether representative administrators, faculty members, and students can complete essential learning management tasks in a realistic test environment, and provides an evidence based basis for acceptance decisions.' 20 $false 'left' 0 240
Tbl @('Document control','Details') @(@('System','LearnSync learning management system'),@('Test type','User Acceptance Test'),@('Prepared for','LearnSync project team and academic stakeholders'),@('Prepared date','14 November 2026'),@('Test status','Ready for execution - results not yet recorded'),@('Confidentiality','Use participant codes only. Do not enter passwords or real student records.')) @(1800,7000)
P 'Acceptance statement' 22 $true 'left' 160 70
P 'A final acceptance decision must be based on completed participant sessions, recorded evidence, and resolution or formal acceptance of all blocking issues. This template does not claim that user acceptance has passed.' 20 $false 'left' 0 0

PageBreak; P '1  Test Overview' 28 $true 'left' 0 120
P 'LearnSync supports academic administration, faculty teaching workflows, and student learning activities. The UAT evaluates whether intended users can complete essential role specific tasks with acceptable clarity, reliability, and usability. The supplied Results and Discussion lesson is used as learning material in the faculty publishing and student learning tasks.' 20 $false 'left' 0 120
P '1.1 Objectives' 22 $true 'left' 120 70
Bullet 'Validate that representative users can complete core tasks without unnecessary assistance.'; Bullet 'Confirm that published learning material, assessments, feedback, grades, and reporting flows are understandable to their intended roles.'; Bullet 'Identify usability concerns, defects, permission issues, and unmet expectations before acceptance.'; Bullet 'Capture structured evidence that can be summarized in the Results and Discussion section of the project report.'
P '1.2 Scope' 22 $true 'left' 140 70
Tbl @('Role','Included acceptance areas') @(@('Administrator','Academic setup, prospectus and subject setup, section and roster management, invitations, and account status.'),@('Faculty','Workspace orientation, grading and feedback, results release, announcements, grade export, and lesson publishing.'),@('Student','Onboarding, next steps and due work, lesson completion, Study Help, quiz and grade results, and issue reporting.')) @(1800,7000)
P '1.3 Test Environment and Entry Criteria' 22 $true 'left' 120 70
Tbl @('Item','Required condition') @(@('Environment','A disposable LearnSync environment with test-only data.'),@('Accounts','Dedicated administrator, faculty, and student accounts; do not record passwords.'),@('Content','A class or section, a Results and Discussion lesson, sample activity submissions, a quiz, and a grade record are prepared.'),@('Facilitator','A facilitator records time, help requested, defects, and observations without coaching task steps.'),@('Participants','At least two to three participants collectively representing administrator, faculty, and student roles.')) @(1800,7000)

PageBreak; P '2  Test Method and Evidence Rules' 28 $true 'left' 0 120
P '2.1 Session Procedure' 22 $true 'left' 120 70
Bullet 'Test one participant at a time. Give the task prompt exactly as written, without naming a page, menu, or button.'; Bullet 'Start timing when the task is read. Stop after three minutes or when the participant asks to stop.'; Bullet 'Record completion status, elapsed time, help required, wrong turns, participant comments, and any observed defect before continuing.'; Bullet 'Do not include names, passwords, student numbers, grades, screenshots containing personal data, or other sensitive information in this document.'; Bullet 'Participants may stop at any time. Testing evaluates the system, not the participant.'
P '2.2 Completion Ratings' 22 $true 'left' 140 70
Tbl @('Rating','Definition','Treatment') @(@('Completed without help','Participant finished independently within three minutes.','Counts as successful completion.'),@('Completed with help','Participant finished after a clarification or navigation help.','Completed, but contributes to usability observation.'),@('Not completed','Participant did not finish, abandoned the task, or encountered a blocking issue.','Requires an observation or defect record.'),@('Not applicable','Task cannot be run because a required condition is unavailable.','Exclude from completion rate; state why.')) @(2200,3300,3300)
P '2.3 Post Test Rating Scale' 22 $true 'left' 120 70
P 'Circle one response for each statement: 5 strongly agree, 4 agree, 3 neither agree nor disagree, 2 disagree, 1 strongly disagree. Record the mean only after at least two participants have answered the item.' 20 $false 'left' 0 80
Tbl @('Mean range','Interpretation') @(@('4.21 - 5.00','Strongly acceptable'),@('3.41 - 4.20','Acceptable'),@('2.61 - 3.40','Neutral / needs review'),@('1.81 - 2.60','Not acceptable'),@('1.00 - 1.80','Strongly not acceptable')) @(2500,6300)
P '2.4 Acceptance Rules' 22 $true 'left' 100 70
Bullet 'No unresolved blocker may remain. A blocker includes data loss, a permission boundary failure, exposed private information, assessment answer exposure, or failure preventing a core role from completing essential work.'; Bullet 'Each role must complete its essential tasks, or an exception must be documented and accepted by the designated approver.'; Bullet 'Overall completion rates, usability ratings, open issues, and participant feedback must be summarized before sign off.'; Bullet 'Conditional acceptance may be used only for non-blocking issues with owners and target dates.'

PageBreak; P '3  Participant and Session Record' 28 $true 'left' 0 120
P 'Complete one participant record per session. Use a non-identifying code rather than a name.' 20 $false 'left' 0 90
Tbl @('Field','Record') @(@('Participant code','____________________________________________'),@('Role','Administrator  /  Faculty  /  Student'),@('Session date and time','____________________________________________'),@('Facilitator','____________________________________________'),@('Device and screen size','____________________________________________'),@('Browser','____________________________________________'),@('Prior LMS experience','None  /  Some  /  Frequent'),@('Test environment / build','____________________________________________')) @(2600,6200)
P 'Facilitator Opening Script' 22 $true 'left' 100 70
P 'We are testing the system, not you. Please work through each task as you normally would. I will not guide you unless you ask to stop. You may stop at any time. We will record your task outcome and feedback, but we will not record passwords or personal information.' 20 $false 'left' 0 120
P 'Task Record Key' 22 $true 'left' 100 70
P 'For each task, record CW = completed without help, CH = completed with help, NC = not completed, or NA = not applicable. Use the observation reference to point to the issue log when needed.' 20 $false 'left' 0 0

function TaskPage([string]$title,[string]$intro,[object[]]$rows,[string]$notes) { PageBreak; P $title 28 $true 'left' 0 120; P $intro 18 $false 'left' 0 100; Tbl @('ID','Task prompt','Expected outcome','Result','Time s','Obs ref') $rows @(500,3200,2500,600,600,700); P $notes 20 $true 'left' 100 70; P '______________________________________________________________________________________________________________________________' 19 $false 'left' 0 70; P '______________________________________________________________________________________________________________________________' 19 $false 'left' 0 0 }
TaskPage '4  Administrator Acceptance Tasks' 'Facilitator: provide the participant with the required prospectus and student list. One student-list row should name a section that does not exist. Do not identify target pages or controls in the prompts.' @(@('A1','Set up the coming semester for the school.','A new academic term is created and ready for setup.','___','___','___'),@('A2','Add the subjects from the curriculum prospectus you were given.','Subjects can be reviewed and added without unexplained errors.','___','___','___'),@('A3','Create a section called 1A and assign a teacher to its subject.','The section and teacher assignment are saved and visible.','___','___','___'),@('A4','Add students from the supplied list to section 1A. One row names a section that does not exist.','Valid rows are handled correctly; the invalid row produces a clear message.','___','___','___'),@('A5','Find an invited person who has not accepted yet and resend their invitation.','The participant identifies the pending invite and completes the resend action.','___','___','___'),@('A6','A student says their account is locked. Find the account, deactivate it, then make it active again.','The status changes are clear and leave the account active.','___','___','___')) 'Administrator Session Notes'
TaskPage '5  Faculty Acceptance Tasks' 'Facilitator: prepare three activity submissions, a grade-ready class, and the supplied Results and Discussion PDF in the test environment.' @(@('F1','Accept your invitation and choose a password.','The account is activated and the participant enters the faculty workspace.','___','___','___'),@('F2','Find out what needs your attention today.','The participant locates the relevant teaching task or indicator.','___','___','___'),@('F3','Grade three activity submissions and give one student feedback.','Scores and feedback are saved for the intended student.','___','___','___'),@('F4','Make the results visible to students.','The release action and its effect are understandable and complete.','___','___','___'),@('F5','Write an announcement for section 1A only.','The announcement is addressed to the correct section and can be published.','___','___','___'),@('F6','Publish the Midterm grade for your class and download it as a PDF.','Grade publication is explicit and the PDF export downloads successfully.','___','___','___'),@('F7','Publish the provided Results and Discussion PDF as a lesson for the appropriate class.','The lesson is published and available to the intended students.','___','___','___')) 'Faculty Session Notes'
TaskPage '6  Student Acceptance Tasks' 'Facilitator: ensure the participant can access the published lesson, a quiz, a released result or grade, and the problem-report function. For S4, do not tell the participant the distinction between reporting results and interpreting them.' @(@('S1','Accept your invitation and choose a password.','The account is activated and the participant enters the student workspace.','___','___','___'),@('S2','Find the next thing you should do.','The participant locates the next applicable learning task.','___','___','___'),@('S3','Find everything due this week across your subjects.','Due work can be found and interpreted without navigation confusion.','___','___','___'),@('S4','Open the Results and Discussion lesson, mark it complete, and ask Study Help to explain one idea in simpler words.','The lesson opens, completion is recorded, and Study Help returns an understandable response when configured.','___','___','___'),@('S5','Take the quiz, then find your result and Midterm grade.','Quiz completion, result access, and grade visibility are understandable.','___','___','___'),@('S6','Report a problem with the page you are on.','The participant can create a clear problem report through the workflow.','___','___','___')) 'Student Session Notes'

PageBreak; P '7  Post Test Questionnaire' 28 $true 'left' 0 120; P 'Ask each participant after role specific tasks. Circle one response: 5 strongly agree, 4 agree, 3 neither agree nor disagree, 2 disagree, 1 strongly disagree.' 20 $false 'left' 0 90
Tbl @('ID','Statement','Rating','Score') @(@('Q1','I could understand what I needed to do next in LearnSync.','5  4  3  2  1','___'),@('Q2','The labels, menus, and buttons were easy to understand.','5  4  3  2  1','___'),@('Q3','The system gave clear feedback after I completed an action.','5  4  3  2  1','___'),@('Q4','I could find important information and tasks without excessive searching.','5  4  3  2  1','___'),@('Q5','The system responded quickly enough for the tasks I performed.','5  4  3  2  1','___'),@('Q6','I would feel comfortable using LearnSync for my regular role.','5  4  3  2  1','___'),@('Q7','The appearance and layout were clear and readable.','5  4  3  2  1','___')) @(500,5400,1700,700)
P 'Open Feedback' 22 $true 'left' 100 70
P '1. What was the most confusing moment? ______________________________________________________________________________________' 19 $false 'left' 0 100; P '2. Was there anything you expected to find but could not? ______________________________________________________________________' 19 $false 'left' 0 100; P '3. What is one change that would make LearnSync easier for you? ________________________________________________________________' 19 $false 'left' 0 100; P '4. Facilitator check for S4 (optional): Can the participant explain the difference between reporting results and discussing their meaning?  Yes / Partly / No' 19 $false 'left' 0 0

PageBreak; P '8  Observation and Defect Log' 28 $true 'left' 0 120; P 'Use one row for each observation. Separate participant feedback from verified defects. Escalate blockers immediately.' 20 $false 'left' 0 90
$issues=@(); 1..8 | ForEach-Object {$issues += ,@("O$_",'________________','Admin / Faculty / Student','Usability / Defect','Low / Medium / High / Blocker','Open','________')}; Tbl @('Ref','Summary','Role','Type','Severity','Status','Owner') $issues @(500,2000,1200,1100,1400,800,900)
P 'Blocking Issue Checklist' 22 $true 'left' 100 70; Bullet 'Data loss or data corruption observed'; Bullet 'Permission boundary failure or access to private information observed'; Bullet 'Assessment answers or restricted results exposed to an unauthorized user'; Bullet 'Core role cannot complete an essential task'; Bullet 'Other critical issue: _______________________________________________'; P 'If any item is checked, do not mark UAT accepted until the issue is resolved or formally addressed in the acceptance decision.' 19 $true 'left' 60 0

PageBreak; P '9  Results Summary and Acceptance Decision' 28 $true 'left' 0 120; P 'Complete this section only after all planned sessions have been completed. Report observed results; do not infer acceptance from scripted checks alone.' 20 $false 'left' 0 90
P '9.1 Task Completion Summary' 22 $true 'left' 100 70; Tbl @('Role','Tasks planned','CW','CH','NC','NA','Completion rate') @(@('Administrator','6','___','___','___','___','___ %'),@('Faculty','7','___','___','___','___','___ %'),@('Student','6','___','___','___','___','___ %'),@('Overall','19','___','___','___','___','___ %')) @(1700,1100,700,700,700,700,2000); P 'Completion rate = (Completed without help + Completed with help) / (Tasks planned - Not applicable) x 100.' 17 $false 'left' 0 100
P '9.2 Questionnaire Summary' 22 $true 'left' 80 70; Tbl @('Item','Mean score','Interpretation','Key evidence or comment') @(@('Q1','','',''),@('Q2','','',''),@('Q3','','',''),@('Q4','','',''),@('Q5','','',''),@('Q6','','',''),@('Q7','','',''),@('Overall','','','')) @(700,1400,2600,2900)
P '9.3 Findings for Results and Discussion' 22 $true 'left' 80 70; P 'Summarize completion rates, questionnaire means, repeated usability concerns, and defect status. Interpret what the findings mean for LearnSync readiness using participant evidence and verified test records. Avoid presenting unfinished sessions or scripted technical checks as completed user acceptance.' 20 $false 'left' 0 100; P 'Summary: ____________________________________________________________________________________________________________________' 19 $false 'left' 0 80; P '______________________________________________________________________________________________________________________________' 19 $false 'left' 0 80; P '______________________________________________________________________________________________________________________________' 19 $false 'left' 0 120
P '9.4 Decision' 22 $true 'left' 80 70; P 'Select one:  [  ] Accepted    [  ] Conditionally accepted    [  ] Not accepted' 22 $true 'left' 0 80; P 'Basis for decision: ________________________________________________________________________________________________________' 19 $false 'left' 0 80; P '______________________________________________________________________________________________________________________________' 19 $false 'left' 0 100
Tbl @('Approval role','Name / signature','Date') @(@('UAT facilitator','____________________________________________','________________'),@('Project representative','____________________________________________','________________'),@('Academic / client approver','____________________________________________','________________')) @(2200,4700,1700)

[void]$sb.Append('<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1250" w:right="1225" w:bottom="1135" w:left="1225" w:header="708" w:footer="708" w:gutter="0"/></w:sectPr></w:body></w:document>')
$utf8 = [Text.UTF8Encoding]::new($false)
[IO.File]::WriteAllText((Join-Path $tmpDir 'word\document.xml'),$sb.ToString(),$utf8)
[IO.File]::WriteAllText((Join-Path $tmpDir '[Content_Types].xml'),'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/></Types>',$utf8)
[IO.File]::WriteAllText((Join-Path $tmpDir '_rels\.rels'),'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>',$utf8)
[IO.File]::WriteAllText((Join-Path $tmpDir 'docProps\core.xml'),'<?xml version="1.0" encoding="UTF-8"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>LearnSync User Acceptance Test</dc:title><dc:subject>User Acceptance Test protocol, records, and sign off</dc:subject><dc:creator>LearnSync Project Team</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">2026-11-14T00:00:00Z</dcterms:created></cp:coreProperties>',$utf8)
[IO.File]::WriteAllText((Join-Path $tmpDir 'docProps\app.xml'),'<?xml version="1.0" encoding="UTF-8"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>Microsoft Office Word</Application></Properties>',$utf8)
if(Test-Path -LiteralPath $outFile){Remove-Item -LiteralPath $outFile -Force}
$archive = [IO.Compression.ZipFile]::Open($outFile,[IO.Compression.ZipArchiveMode]::Create)
try {
  Get-ChildItem -LiteralPath $tmpDir -Recurse -File | ForEach-Object {
    $relative = $_.FullName.Substring($tmpDir.Length + 1).Replace('\','/')
    [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($archive,$_.FullName,$relative,[IO.Compression.CompressionLevel]::Optimal) | Out-Null
  }
} finally { $archive.Dispose() }
Remove-Item -LiteralPath $tmpDir -Recurse -Force
Write-Output $outFile
